#!/usr/bin/env node
/**
 * MCP reference drift check.
 *
 * docs/mcp/tools/*.md, docs/mcp/resources.md, docs/mcp/playbooks.md and
 * docs/cli/agentdash-connect.md are generated by
 * scripts/docs/generate-mcp-reference.mjs from the MCP server's own
 * `tools/list`, resource listings and instructions, and from
 * packages/connect/README.md. They are committed so the docs bundle can import
 * them. This check regenerates them into a temp directory and fails when the
 * committed copy differs — so a PR that changes a tool, a schema, a playbook or
 * the connect README without regenerating fails here instead of publishing a
 * reference that is wrong (doc/plans/2026-10-01-public-docs-section.md,
 * "Generated references and drift checks").
 *
 * The generating-commit line in each header is ignored: it names the commit
 * the generator ran on, which is never the commit that contains its output.
 * Any committed file under docs/mcp/tools/ that the generator does not produce
 * fails too — that directory is generated, whole.
 *
 * Usage: node scripts/ci/check-mcp-reference-drift.mjs
 *
 * Exit codes: 0 — current; 1 — drift; 2 — the generator itself failed.
 */

import { existsSync, mkdtempSync, readFileSync, readdirSync, realpathSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  GENERATED_FILES,
  generateMcpReference,
  withoutCommitLine,
  writeGenerated,
} from "../docs/generate-mcp-reference.mjs";

export const GENERATED_DIRS = ["docs/mcp/tools"];
const CONTEXT_LINES = 4;

/** Markdown files under `dir` (repo-relative), recursively. */
function listMarkdown(root, rel) {
  const dir = path.join(root, rel);
  if (!existsSync(dir)) return [];
  const out = [];
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const child = `${rel}/${entry.name}`;
    if (entry.isDirectory()) out.push(...listMarkdown(root, child));
    else if (/\.mdx?$/.test(entry.name)) out.push(child);
  }
  return out.sort();
}

/**
 * Where two texts differ: the first and last differing line, and a few lines
 * of each side. Not a full diff — enough to see what moved.
 */
export function diffSummary(committed, generated) {
  const a = committed.split("\n");
  const b = generated.split("\n");
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) start += 1;
  let endA = a.length - 1;
  let endB = b.length - 1;
  while (endA >= start && endB >= start && a[endA] === b[endB]) {
    endA -= 1;
    endB -= 1;
  }
  const lines = [`  first difference at line ${start + 1}; committed lines ${start + 1}-${endA + 1} vs generated lines ${start + 1}-${endB + 1}`];
  for (const line of a.slice(start, Math.min(endA + 1, start + CONTEXT_LINES))) lines.push(`  - ${line.slice(0, 160)}`);
  for (const line of b.slice(start, Math.min(endB + 1, start + CONTEXT_LINES))) lines.push(`  + ${line.slice(0, 160)}`);
  return lines.join("\n");
}

/**
 * Compare the generated tree with the committed one. `expected` is the list of
 * files the generator writes; any other file in a generated directory is
 * reported as unexpected.
 */
export function compareGenerated({ generatedRoot, committedRoot, expected = GENERATED_FILES, generatedDirs = GENERATED_DIRS }) {
  const problems = [];
  for (const rel of expected) {
    const generatedPath = path.join(generatedRoot, rel);
    const committedPath = path.join(committedRoot, rel);
    if (!existsSync(generatedPath)) {
      problems.push({ rel, kind: "not-generated", detail: "  the generator did not produce this file" });
      continue;
    }
    if (!existsSync(committedPath)) {
      problems.push({ rel, kind: "missing", detail: "  generated but not committed" });
      continue;
    }
    const committed = withoutCommitLine(readFileSync(committedPath, "utf8"));
    const generated = withoutCommitLine(readFileSync(generatedPath, "utf8"));
    if (committed !== generated) problems.push({ rel, kind: "stale", detail: diffSummary(committed, generated) });
  }
  const expectedSet = new Set(expected);
  for (const dir of generatedDirs) {
    for (const rel of listMarkdown(committedRoot, dir)) {
      if (!expectedSet.has(rel)) {
        problems.push({ rel, kind: "unexpected", detail: `  committed under ${dir}/, which is generated, but the generator does not produce it` });
      }
    }
  }
  return problems;
}

export function formatProblems(problems) {
  return [
    `MCP reference is stale: ${problems.length} ${problems.length === 1 ? "file differs" : "files differ"} from what the MCP server generates.`,
    "",
    ...problems.map((problem) => `${problem.rel} (${problem.kind})\n${problem.detail}`),
    "",
    "Regenerate and commit: pnpm docs:mcp-reference",
    "(node scripts/docs/generate-mcp-reference.mjs; then pnpm docs:search-index, since the search index reads these pages)",
  ].join("\n");
}

async function main() {
  const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
  const generatedRoot = mkdtempSync(path.join(tmpdir(), "mcp-reference-check-"));
  try {
    let files;
    try {
      files = await generateMcpReference(repoRoot);
    } catch (error) {
      console.error("MCP reference generator failed:", error);
      process.exit(2);
    }
    writeGenerated(files, generatedRoot);
    const problems = compareGenerated({ generatedRoot, committedRoot: repoRoot });
    if (problems.length > 0) {
      console.error(formatProblems(problems));
      process.exit(1);
    }
    console.log(`MCP reference is current (${GENERATED_FILES.length} generated files).`);
  } finally {
    rmSync(generatedRoot, { recursive: true, force: true });
  }
}

// Entry guard: resolve symlinks on both sides (scripts/entry-guard.test.mjs; cf. #666).
function realOrResolved(p) {
  try {
    return realpathSync(p);
  } catch {
    return path.resolve(p);
  }
}
if (process.argv[1] && realOrResolved(process.argv[1]) === realOrResolved(fileURLToPath(import.meta.url))) {
  await main();
}
